codeExamples.code:
-- Covering index: key on customer_id, output columns INCLUDEd
CREATE NONCLUSTERED INDEX IX_Orders_customer_covering
    ON Orders (customer_id)
    INCLUDE (order_date, total_amount);

-- Now satisfied entirely from the index leaf: NO key lookup
SELECT customer_id, order_date, total_amount
FROM Orders
WHERE customer_id = 42;

-- Low-selectivity example the optimizer will likely IGNORE:
-- status has few distinct values, so this scans instead of seeking
CREATE NONCLUSTERED INDEX IX_Orders_status ON Orders (customer_id);
SELECT * FROM Orders WHERE customer_id IS NOT NULL;
